import taf.gnb.oam.megazone_client.session_handler as megazone_session_handler
import logging
from .socat_session import SocatSession
import time

log = logging.getLogger(__name__)


class MaxRetryError(Exception):
    pass


class SessionHandler(object):
    def __init__(self):
        self.socat_session = SocatSession()
        self.session_handler = megazone_session_handler.SessionHandler()

    def _start_socat(self, base_url, connection, socat_port, fsm_ip, fsm_port,
                     creation_attempts=5):
        socat_started = False
        socat_retries = 0
        while not socat_started and socat_retries < creation_attempts:
            socat_retries += 1
            self.socat_session.start_socat(socat_port=socat_port,
                                           connection=connection,
                                           fsm_ip=fsm_ip, fsm_port=fsm_port)
            time.sleep(2)
            socat_started = self.socat_session.check_connection(base_url,
                                                                socat_port)
        self._check_max_creation_attempts_reached(retries=socat_retries,
                                                  max_retries=creation_attempts)

    def _check_max_creation_attempts_reached(self, retries, max_retries):
        if retries >= max_retries:
            msg = 'Socat creation failed after {} retries.'.format(retries)
            raise MaxRetryError(msg)

    def send_request(self, url, method='GET', headers=None, **kwargs):
        """
        Send request using python's request library. Except defined arguments
        any named argument described in request library for used method
        can be used. If no header defined for POST and PUT methods, then
        default json header will be used.
        :param url: REST uri, only ending needed, full url will be created from
        ip defined during session creation
        :param method: REST GET by default, available methods are: GET, POST,
        PUT
        :param headers: headers dictionary which should be attached to request
        """
        return self.session_handler.send_request(url=url,
                                                 method=method,
                                                 headers=headers,
                                                 **kwargs)

    def create_session(self, base_url, connection, socat_port,
                       fsm_ip, fsm_port):
        base_url = self._process_url(base_url)
        self._start_socat(base_url=base_url, connection=connection,
                          socat_port=socat_port, fsm_ip=fsm_ip,
                          fsm_port=fsm_port)
        self.session_handler.create_session(base_url=base_url, port=socat_port)

    def create_direct_session(self, fsm_ip, nodeoam_port):
        fsm_ip = self._process_url(fsm_ip)
        self.session_handler.create_session(base_url=fsm_ip, port=nodeoam_port)

    def _process_url(self, url):
        url = url.rstrip('/')
        if not url.startswith('http'):
            log.debug("No protocol defined by user, http will be used.")
            url = 'http://' + url
        return url
